#!/usr/bin/env bash
# Baut eine Doku-Seite mit gemeinsamem Kopf/Fuß: tools/mkpage.sh <ziel.html> "<Titel>" <IDX|ENT|SPE|BEN|TBM|ANL|REC> <body.html>
set -euo pipefail
NAV='<header><div class="wrap"><a class="brand" href="index.html">GLM-5.3-Flash auf Strix Halo</a><nav><a href="index.html"%IDX%>Überblick</a><a href="entscheidungen.html"%ENT%>Entscheidungen</a><a href="speicher.html"%SPE%>Speicher</a><a href="benchmarks.html"%BEN%>Messungen</a><a href="terminal-bench.html"%TBM%>Terminal-Bench</a><a href="anleitung.html"%ANL%>Anleitung</a><a href="recherche.html"%REC%>Recherche &amp; Quellen</a><a class="gh" href="https://github.com/kksoftwareag/strix-halo-glm-5.3-flash" rel="noopener"><svg viewBox="0 0 16 16" aria-hidden="true"><path d="M8 0C3.58 0 0 3.58 0 8c0 3.54 2.29 6.53 5.47 7.59.4.07.55-.17.55-.38 0-.19-.01-.82-.01-1.49-2.01.37-2.53-.49-2.69-.94-.09-.23-.48-.94-.82-1.13-.28-.15-.68-.52-.01-.53.63-.01 1.08.58 1.23.82.72 1.21 1.87.87 2.33.66.07-.52.28-.87.51-1.07-1.78-.2-3.64-.89-3.64-3.95 0-.87.31-1.59.82-2.15-.08-.2-.36-1.02.08-2.12 0 0 .67-.21 2.2.82.64-.18 1.32-.27 2-.27s1.36.09 2 .27c1.53-1.04 2.2-.82 2.2-.82.44 1.1.16 1.92.08 2.12.51.56.82 1.27.82 2.15 0 3.07-1.87 3.75-3.65 3.95.29.25.54.73.54 1.48 0 1.07-.01 1.93-.01 2.2 0 .21.15.46.55.38A8.01 8.01 0 0 0 16 8c0-4.42-3.58-8-8-8Z"/></svg>GitHub</a></nav></div></header>'
FOOT='<footer><div class="wrap">Stand: 5. September 2026 · Vorbereitung auf einem Ryzen AI MAX+ 395 (Radeon 8060S, 128 GB) unter Fedora 44, ROCm/HIP 7.1 · Messungen ausstehend · Projekt: <a href="https://github.com/kksoftwareag/strix-halo-glm-5.3-flash">kksoftwareag/strix-halo-glm-5.3-flash</a> · Diese Seiten liegen im Ordner <code>docs/</code> des Projekts</div></footer>'
f=$1; t=$2; k=$3; body=$4; nav="$NAV"
for key in IDX ENT SPE BEN TBM ANL REC; do if [ "$key" = "$k" ]; then nav="${nav//%$key%/ aria-current=\"page\"}"; else nav="${nav//%$key%/}"; fi; done
{ printf '<!doctype html>\n<html lang="de">\n<head>\n<meta charset="utf-8">\n<meta name="viewport" content="width=device-width, initial-scale=1">\n<title>%s · GLM-5.3-Flash auf Strix Halo</title>\n<meta name="description" content="Dokumentation der Entscheidungen, Messungen und Quellen zum Betrieb von GLM-5.3-Flash mit llama.cpp (MTP) auf AMD Strix Halo.">\n<link rel="stylesheet" href="style.css">\n</head>\n<body>\n%s\n<main><div class="wrap">\n' "$t" "$nav"; cat "$body"; printf '\n</div></main>\n%s\n</body>\n</html>\n' "$FOOT"; } > "$f"
